// The semantic rows and primary anchors are transcribed from Fable Part 5.
import { clamp, hexChannel, q16, srgbLinear16 } from "./color.ss.ts";
import { setRecipeWord } from "./recipe.ss.ts";
import { BAD_ARGUMENT, BAD_INPUT, CONFIG, RECIPE, WORKSPACE_WORDS, mod, zeroWords } from "./types.ss.ts";
import type { WallpaperFamily, WallpaperMode, WallpaperPolarity, WallpaperTier } from "./types.ss.ts";

export type WallpaperPreset = {
  readonly id: number;
  readonly family: WallpaperFamily;
  readonly slug: string;
  readonly polarity: WallpaperPolarity;
  readonly tier: WallpaperTier;
  readonly mode: WallpaperMode;
  readonly dynamics: string;
  readonly zenith: string;
  readonly zenithR: number;
  readonly zenithG: number;
  readonly zenithB: number;
  readonly ambientGain: number;
  readonly accent: string;
  readonly accentSlot: string;
  readonly referenceRecipeBytes: number;
  readonly budget: string;
  readonly description: string;
  readonly base: string;
  readonly horizon: string;
  readonly top: string;
};

export function wallpaperPresetCount(): number { return 200; }

function paletteValue(face: number, polarity: number, rgb: number, anchor: number, channel: number): number {
  const code = hexChannel(rgb, channel);
  if (polarity === 2 && face === 1) {
    // Low-chroma paper tints preserve the warm/cool order of the dark anchors.
    return srgbLinear16(Math.floor(clamp(216 + anchor * 12 + (code - 128) / 16, 209, 255)));
  }
  return srgbLinear16(code);
}

function writePreset(
  workspace: number[], id: number, family: number, polarity: number, tier: number,
  mode: number, base: number, horizon: number, top: number,
  zenithRG: number, zenithBA: number, lightBinding: number,
): number {
  zeroWords(workspace, RECIPE(), RECIPE() + 120);
  workspace[CONFIG() + 1] = id;
  workspace[CONFIG() + 2] = polarity;
  setRecipeWord(workspace, 4, id);
  setRecipeWord(workspace, 5, family);
  setRecipeWord(workspace, 6, id * 2654435761 - Math.floor(id * 2654435761 / 4294967296) * 4294967296);
  setRecipeWord(workspace, 7, tier);
  setRecipeWord(workspace, 8, mode);
  setRecipeWord(workspace, 9, 63);
  setRecipeWord(workspace, 10, 65535);
  setRecipeWord(workspace, 11, 5243);
  setRecipeWord(workspace, 12, q16(.45 + mod(id, 11) * .035));
  setRecipeWord(workspace, 13, mod(id - 1, 20));
  setRecipeWord(workspace, 14, 8192);
  setRecipeWord(workspace, 15, 16384);
  for (let layer = 0; layer < 6; layer++) {
    const at = 16 + 12 * layer;
    setRecipeWord(workspace, at, layer);
    setRecipeWord(workspace, at + 1, 1);
    setRecipeWord(workspace, at + 2, layer === 2 || layer === 4 ? 1 : 0);
    setRecipeWord(workspace, at + 3, layer === 0 || layer === 5 ? 65535 : 8500 + mod(id * 719 + layer * 1543, 12000));
    setRecipeWord(workspace, at + 4, q16(layer * .2));
    setRecipeWord(workspace, at + 5, q16(.2 + mod(id * 7, 61) / 100));
    setRecipeWord(workspace, at + 6, q16(.25 + mod(id * 3, 51) / 100));
    setRecipeWord(workspace, at + 7, 256 + mod(id * 37, 640));
    setRecipeWord(workspace, at + 8, 32768);
    setRecipeWord(workspace, at + 9, 0);
    setRecipeWord(workspace, at + 10, 3);
    setRecipeWord(workspace, at + 11, mod(id * 1049, 65536));
  }
  let low = 0;
  for (let i = 0; i < 18; i++) {
    const face = Math.floor(i / 9);
    const anchor = Math.floor(mod(i, 9) / 3);
    const rgb = anchor === 0 ? base : anchor === 1 ? horizon : top;
    const value = paletteValue(face, polarity, rgb, anchor, mod(i, 3));
    if (mod(i, 2) === 0) low = value;
    else setRecipeWord(workspace, 112 + Math.floor(i / 2), low + 65536 * value);
  }
  setRecipeWord(workspace, 121, zenithRG);
  setRecipeWord(workspace, 122, zenithBA);
  setRecipeWord(workspace, 123, lightBinding);
  return 0;
}

export function wallpaperPreset(id: number): WallpaperPreset | undefined {
  if (id < 1 || id > 200 || Math.floor(id) !== id) return undefined;
  return presetRow(id);
}

